// Des: Pull car rows from stored pages, mark gone listings
// Flo: pages (code 200) not yet in carz, changed since, or older parser > detail URLs only > unchanged page just moves lasz > else load raw, parse, save (at most carz_pull_maxz parses) > sold notice marks gone > 404/410 pages and rows not seen for carz_dead_days are marked gone
// I/O: open Db + data dir + Conf + clock (caller) > Pres counts; dryz counts without reading raw files or writing
// ===================================================================
const std = @import("std"); const cfgz = @import("cf-conf-load.zig"); const sqli = @import("st-stor-sqli.zig"); const stor = @import("st-carz-stor.zig"); const pars = @import("pa-carz-pars.zig"); const help = @import("pa-carz-help.zig"); const file = @import("st-stor-file.zig"); const hash = @import("ut-hash-dedu.zig"); const cont = @import("st-cont-stor.zig"); const soci = @import("pa-carz-soci.zig");
const CF = .{ .dayz = 86400000, .rawd = "raw", .maxb = 8 << 20 };
pub const Pres = struct { cnts: u32 = 0, seen: u32 = 0, pars: u32 = 0, skip: u32 = 0, lost: u32 = 0, news: u32 = 0, chan: u32 = 0, same: u32 = 0, gone: u32 = 0 };
const Cand = struct { urlz: []const u8, hexz: []const u8, fetc: i64, fast: bool };
fn yearOfzz(nowz: i64) i64 { const secs: u64 = @intCast(@max(@divFloor(nowz, 1000), 0)); const epsz: std.time.epoch.EpochSeconds = .{ .secs = secs }; return epsz.getEpochDay().calculateYearDay().year; }
fn candList(dbzz: *sqli.Dbzz, aren: std.mem.Allocator) ![]Cand { var list: std.ArrayList(Cand) = .empty; var stmt = try dbzz.prep("SELECT p.urlz,p.hexz,p.fetc,c.urlz IS NOT NULL AND c.hexz=p.hexz AND c.pver=?1 FROM page p LEFT JOIN carz c ON c.urlz=p.urlz WHERE p.code=200 AND (c.urlz IS NULL OR c.hexz<>p.hexz OR c.pver<>?1 OR c.lasz<p.fetc) ORDER BY p.fetc;"); defer stmt.fini(); try stmt.bindIntz(1, pars.VERS); while (try stmt.step()) { try list.append(aren, .{ .urlz = try aren.dupe(u8, stmt.colzText(0)), .hexz = try aren.dupe(u8, stmt.colzText(1)), .fetc = stmt.colzIntz(2), .fast = stmt.colzIntz(3) == 1 }); } return list.toOwnedSlice(aren); }
fn toucLasz(dbzz: *sqli.Dbzz, urlz: []const u8, fetc: i64) !void { var stmt = try dbzz.prep("UPDATE carz SET lasz=MAX(lasz,?2),stat=0,gone=0,grsn='' WHERE urlz=?1;"); defer stmt.fini(); try stmt.bindText(1, urlz); try stmt.bindIntz(2, fetc); _ = try stmt.step(); }
pub fn pullRunz(dbzz: *sqli.Dbzz, iozz: std.Io, dirz: []const u8, conf: cfgz.Conf, gpaz: std.mem.Allocator, nowz: i64, dryz: bool) !Pres { var rslt: Pres = .{}; var cand = std.heap.ArenaAllocator.init(gpaz); defer cand.deinit(); const list = try candList(dbzz, cand.allocator()); var stoz = try stor.storOpen(dbzz, nowz); const rawd = try std.fs.path.join(cand.allocator(), &.{ dirz, CF.rawd }); const nowy = yearOfzz(nowz);
    for (list) |item| { rslt.seen += 1; if (!help.detaUrlz(item.urlz) and !soci.sociHost(help.hostOfzz(item.urlz))) { rslt.skip += 1; continue; } if (item.fast) { rslt.same += 1; if (!dryz) try toucLasz(dbzz, item.urlz, item.fetc); continue; } if (rslt.pars >= conf.carz_pull_maxz) { rslt.skip += 1; continue; } rslt.pars += 1; if (dryz) continue; if (!hash.hashOkay(item.hexz)) { rslt.lost += 1; continue; } var hexz: hash.Hexz = undefined; @memcpy(&hexz, item.hexz[0..64]); var aren = std.heap.ArenaAllocator.init(gpaz); defer aren.deinit(); const html = file.fileLoad(aren.allocator(), iozz, rawd, hexz, CF.maxb) catch { rslt.lost += 1; continue; }; const carz = pars.carzPars(aren.allocator(), item.urlz, html, nowy) catch { rslt.lost += 1; continue; }; if (carz.make.len == 0 or (carz.year == 0 and carz.pric == 0 and !std.mem.eql(u8, carz.sell, "buyer"))) { rslt.skip += 1; continue; } switch (try stor.carzSave(&stoz, carz, item.hexz, item.fetc)) { .news => rslt.news += 1, .chan => rslt.chan += 1, .same => rslt.same += 1 } if (conf.cont_enab) { try cont.contSave(&stoz, carz, item.fetc, conf.cont_priv_enab); if (carz.cnam.len > 0 or carz.phon.len > 0 or carz.cadd.len > 0) rslt.cnts += 1; } if (carz.gone) { try stor.goneMark(&stoz, item.urlz, nowz, "page"); rslt.gone += 1; } }
    if (!dryz) { rslt.gone += try stor.goneHttp(&stoz, nowz); rslt.gone += try stor.goneDead(&stoz, nowz, @as(i64, conf.carz_dead_days) * CF.dayz); } return rslt; }
